class Solution(object):


    def maxNumberOfFamilies(self, n, reservedSeats):
        output = 0
        """
        :type n: int
        :type reservedSeats: List[List[int]]
        :rtype: int
        """
        i = 1
        t=1
        free=0
        freeinarow=0
        maxFamilyOutput=0
        leftfam=False
        midfam=False
        rightfam=False
        while i<=n:
            #is da row der?
            if not(any(seat[0] == i for seat in reservedSeats)):
                maxFamilyOutput+=2
            #checking left
            else:
                if not([i, 2] in reservedSeats or [i, 3] in reservedSeats or [i, 4] in reservedSeats or [i,5] in reservedSeats):
                    leftfam=True
            #checking mid
                if not([i, 4] in reservedSeats or [i, 5] in reservedSeats or [i, 6] in reservedSeats or [i,7] in reservedSeats):
                    midfam=True
            #checking right
                if not([i, 6] in reservedSeats or [i, 7] in reservedSeats or [i, 8] in reservedSeats or [i,9] in reservedSeats):
                    rightfam=True


            if rightfam and leftfam:
                maxFamilyOutput+=2
            elif midfam:
                maxFamilyOutput += 1
            elif rightfam:
                maxFamilyOutput+=1
            elif leftfam:
                maxFamilyOutput+=1
            print("row "+ str(i)+" can fit "+str(maxFamilyOutput)+" famalies")
            i+=1
            t=1
            free=0
            freeinarow = 0
            leftfam = False
            midfam = False
            rightfam = False

        print("max families to fit is "+str(maxFamilyOutput))
        return maxFamilyOutput
